sealed class FixtureHandler:HttpMessageHandler
{
public string Reply="{}",Body="";public int Calls;public HttpStatusCode Status=HttpStatusCode.OK;public TimeSpan Delay;
protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token){Calls++;Body=await request.Content!.ReadAsStringAsync(token);if(Delay>TimeSpan.Zero)await Task.Delay(Delay,token);var response=new HttpResponseMessage(Status){Content=new StringContent(Reply)};if((int)Status==429)response.Headers.RetryAfter=new(TimeSpan.Zero);return response;}
}






